import numpy as np
I4=np.array([[1,1,0,2],[0,1,1,2],[2,2,2,2]])
O4=np.array([[1,1,0,1,1,0,2,2],[0,1,1,0,1,1,0,2],[2,2,0,1,1,0,1,1],[0,2,2,0,1,1,0,1]])
I6=np.array([[0,0,1,2],[1,0,1,2],[2,2,2,2]])
O6=np.array([[0,0,2,0,0,2,0,0],[2,0,2,2,0,2,1,0],[0,0,1,0,0,2,0,0],[1,0,1,2,0,2,1,0]])
# relation direct or swap (1<->2), fixed 0
for r in range(4):
    for c in range(8):
        candidates=[]
        preds=set()
        for i in range(3):
            for j in range(4):
                for sw in [False,True]:
                    def f(x): return (3-x if x in (1,2) else x) if sw else x
                    if f(I4[i,j])==O4[r,c] and f(I6[i,j])==O6[r,c]:
                        candidates.append((i,j,sw))
                        preds.add(f(np.array([[1,1,0,2],[0,0,0,2],[2,2,2,2]])[i,j]))
        print((r,c),'cand',candidates,'pred',preds)
    print()

